    Return the 0-based index of x in the strictly ascending list xs, or None if x is absent.

    pre: all(xs[i] < xs[i + 1] for i in range(len(xs) - 1))
    post: (__return__ is None and x not in xs) or (__return__ is not None and 0 <= __return__ < len(xs) and xs[__return__] == x)
    """
    lo, hi = (0, len(xs) - 1)
    while lo <= hi:
        mid = (lo + hi) // 2
        if xs[mid] == x:
            return mid
        if xs[mid] < x:
            lo = mid + 1
        else:
            hi = mid + 1
    return None

