    for x in xs:
        if x == v:
            c += 1
    return c

def _has_majority(xs):
    for v in xs:
        if 2 * _count(xs, v) > len(xs):
            return True
    return False

def majority(xs: list[int]) -> int | None:
    """Return the value occurring in more than half of the positions of xs, or None.

    post: (__return__ is None) == (not _has_majority(xs))
    post: __return__ is None or 2 * _count(xs, __return__) > len(xs)
    """
    cand = None
    n = 0
    for x in xs:
        if n == 0:
            cand = x
            n = 1
        elif x == cand:
            n += 1
        else:
            n -= 1
    if cand is not None and 2 * _count(xs, cand) > len(xs):
        return cand
    return None

